func equal(a, b []int) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func TestPrefixFunctionKnownCases(t *testing.T) {
	cases := []struct {
		s    string
		want []int
	}{
		{"", []int{}},
		{"a", []int{0}},
		{"aabaaab", []int{0, 1, 0, 1, 2, 2, 3}},
		{"abcabcd", []int{0, 0, 0, 1, 2, 3, 0}},
		{"aaaa", []int{0, 1, 2, 3}},
		{"abababca", []int{0, 0, 1, 2, 3, 4, 0, 1}},
