package lcdrill

// O(n^2) Prim over an adjacency list: no n*n memory, but a full vertex scan per step.
func minimumSpanningTree(n int, edges [][]int) int {
	const inf = 1 << 30
	type arc struct{ to, w int }
	adj := make([][]arc, n)
	for _, e := range edges {
		adj[e[0]] = append(adj[e[0]], arc{e[1], e[2]})
		adj[e[1]] = append(adj[e[1]], arc{e[0], e[2]})
	}
	dist := make([]int, n)
	done := make([]bool, n)
	for i := range dist {
		dist[i] = inf
	}
	dist[0] = 0
	total := 0
	for it := 0; it < n; it++ {
		u := -1
		for v := 0; v < n; v++ {
			if !done[v] && (u == -1 || dist[v] < dist[u]) {
				u = v
			}
		}
		if dist[u] == inf {
			return -1
		}
		done[u] = true
		total += dist[u]
		for _, a := range adj[u] {
			if !done[a.to] && a.w < dist[a.to] {
				dist[a.to] = a.w
			}
		}
	}
	return total
}
