package lcdrill

import "sort"

// Wrong-but-plausible: cheapest edge first, kept when an endpoint is new.
func minimumSpanningTree(n int, edges [][]int) int {
	if n <= 1 {
		return 0
	}
	es := make([][]int, len(edges))
	copy(es, edges)
	sort.Slice(es, func(a, b int) bool { return es[a][2] < es[b][2] })
	seen := make([]bool, n)
	total, joined := 0, 0
	for _, e := range es {
		if seen[e[0]] && seen[e[1]] {
			continue
		}
		seen[e[0]], seen[e[1]] = true, true
		total += e[2]
		joined++
	}
	if joined != n-1 {
		return -1
	}
	return total
}
